package negocio;
import java.util.*;
public class TorneoGrupo {
 private long id, torneoCategoriaId; private String nombre; private int orden, capacidad; private ModoAsignacionGrupoTorneo modoAsignacion=ModoAsignacionGrupoTorneo.MANUAL; private boolean confirmado; private final List<TorneoGrupoIntegrante> integrantes=new ArrayList<>();
 public long getId(){return id;} public void setId(long v){id=v;} public long getTorneoCategoriaId(){return torneoCategoriaId;} public void setTorneoCategoriaId(long v){torneoCategoriaId=v;} public String getNombre(){return nombre;} public void setNombre(String v){nombre=v;} public int getOrden(){return orden;} public void setOrden(int v){orden=v;} public int getCapacidad(){return capacidad;} public void setCapacidad(int v){capacidad=v;} public ModoAsignacionGrupoTorneo getModoAsignacion(){return modoAsignacion;} public void setModoAsignacion(ModoAsignacionGrupoTorneo v){modoAsignacion=v;} public boolean isConfirmado(){return confirmado;} public void setConfirmado(boolean v){confirmado=v;} public List<TorneoGrupoIntegrante> getIntegrantes(){return new ArrayList<>(integrantes);} public void setIntegrantes(List<TorneoGrupoIntegrante> v){integrantes.clear();if(v!=null)integrantes.addAll(v);} public int getDisponibles(){return Math.max(0,capacidad-integrantes.size());} public String toString(){return nombre+" ("+integrantes.size()+"/"+capacidad+")";} }
